mapper.select:
WITH materialName_tab AS (
SELECT #{name} name FROM dual
)
SELECT R.ID, R.RECIPE_ID, R.RECIPE_EQUIP_CODE, R.RECIPE_MATERIAL_CODE, R.RECIPE_MATERIAL_NAME, B.SAP_MATERIAL_CODE, R.RECIPE_VERSION_ID, R.RECIPE_TYPE, T.RECIPE_TYPE_NAME, R.PRODUCT_STAGE, ifnull(R.SUMMER_MIX_TIME, 0) SUMMER_MIX_TIME, ifnull(R.LOT_TOTAL_WEIGHT, 0) LOT_TOTAL_WEIGHT, B.MAJOR_TYPE, B.MINPARK_TIME, W.ID AS WEIGHTID, W.SET_WEIGHT, W.RECIPE_MATERIAL_CODE AS WEIGHT_MATERIAL_CODE, W.RECIPE_MATERIAL_NAME AS WEIGHT_MATERIAL_NAME, B2.MAJOR_TYPE AS WEIGHT_MAJOR_TYPE, ROUND(ifnull(R2.LOT_TOTAL_WEIGHT/R.LOT_TOTAL_WEIGHT, 1), 4) CONVERSION_RATIO FROM T_MES_PMT_RECIPE R INNER JOIN T_RECIPE_TYPE T ON T.RECIPE_TYPE_CODE = R.RECIPE_TYPE AND T.DEL_FLAG = '0' LEFT JOIN T_MES_PMT_RECIPE_WEIGHT W ON R.RECIPE_ID = W.FATHER_RECIPE_ID AND W.Del_Flag = '0' AND W.SET_WEIGHT IS NOT NULL LEFT JOIN T_MES_BAS_MATERIAL B ON B.MATERIAL_CODE = R.RECIPE_MATERIAL_CODE AND B.Del_Flag = '0' LEFT JOIN T_MES_BAS_MATERIAL B2 ON B2.MATERIAL_CODE = W.RECIPE_MATERIAL_CODE AND B2.Del_Flag = '0' LEFT JOIN (SELECT MIN(LOT_TOTAL_WEIGHT) LOT_TOTAL_WEIGHT, RECIPE_MATERIAL_CODE FROM T_MES_PMT_RECIPE R2 WHERE R2.AUDIT_FLAG = '1' AND R2.RECIPE_STATE = '1' AND R2.DEL_FLAG = '0' AND (R2.MIX_AREA = #{params.mixArea} AND (R2.RECIPE_TYPE = '1' OR NOT EXISTS (SELECT 0 FROM T_MES_PMT_RECIPE R3 WHERE R3.RECIPE_MATERIAL_CODE = R2.RECIPE_MATERIAL_CODE AND R3.AUDIT_FLAG = '1' AND R3.RECIPE_STATE = '1' AND R3.RECIPE_TYPE = '1' AND R3.DEL_FLAG = '0' AND R3.MIX_AREA = R2.MIX_AREA)) OR NOT EXISTS (SELECT 0 FROM T_MES_PMT_RECIPE R3 WHERE R3.RECIPE_MATERIAL_CODE = R2.RECIPE_MATERIAL_CODE AND R3.AUDIT_FLAG = '1' AND R3.RECIPE_STATE = '1' AND R3.DEL_FLAG = '0' AND R3.MIX_AREA = #{params.mixArea})) GROUP BY RECIPE_MATERIAL_CODE) R2 ON R2.RECIPE_MATERIAL_CODE = W.RECIPE_MATERIAL_CODE WHERE R.AUDIT_FLAG = '1' AND R.RECIPE_STATE = '1' AND R.DEL_FLAG = '0' AND B.DEL_FLAG = '0' AND R.mix_area = #{params.mixArea}
AND R.RECIPE_MATERIAL_NAME = #{params.recipeMaterialName}
AND R.RECIPE_EQUIP_CODE = #{params.recipeEquipCode}
AND R.RECIPE_TYPE = #{params.recipeType}
AND T.recipe_type_name NOT LIKE '%F%' -- 过滤掉试制的
AND (T.recipe_type_name LIKE '%F%' OR T.recipe_type_name = 'PTZ' )
AND EXISTS ( SELECT 0 FROM materialName_tab m WHERE m.name = r.RECIPE_MATERIAL_NAME )
order by R.RECIPE_EQUIP_CODE, R.RECIPE_MATERIAL_CODE, R.RECIPE_VERSION_ID desc

WITH temp_table AS (
SELECT #{item,jdbcType=VARCHAR} material_name FROM dual
) SELECT R.ID, R.RECIPE_ID, R.RECIPE_EQUIP_CODE, R.RECIPE_MATERIAL_CODE, R.RECIPE_MATERIAL_NAME, R.RECIPE_VERSION_ID, R.RECIPE_TYPE, RT.RECIPE_TYPE_NAME, R.PRODUCT_STAGE, R.MIX_AREA, M.MACHINE_NAME FROM T_MES_PMT_RECIPE R INNER JOIN T_LHFL_MACHINE M ON M.MACHINE_CODE = R.RECIPE_EQUIP_CODE AND M.STATUS = '0' AND M.DEL_FLAG = '0' INNER JOIN T_ACCESSORIES_MACHINE AM ON AM.MACHINE_CODE = M.MACHINE_CODE AND AM.Material_Name = R.RECIPE_MATERIAL_NAME AND AM.DEL_FLAG = '0' INNER JOIN T_RECIPE_TYPE RT ON RT.RECIPE_TYPE_CODE = R.RECIPE_TYPE AND RT.DEL_FLAG = 0 WHERE R.RECIPE_STATE = '1' AND R.AUDIT_FLAG = '1' AND R.DEL_FLAG = '0'
AND R.MIX_AREA = #{mixArea}
AND R.RECIPE_MATERIAL_NAME in (SELECT material_name FROM temp_table) ORDER BY r.recipe_material_name, am.machine_order
